import torchfrom sentence_transformers import SentenceTransformer, utilclass VectorRAGPipeline:    """Pipeline RAG Berbasis Representasi Vektor dan Kosinus Similaritas."""    def __init__(self, model_name: str = "sentence-transformers/all-MiniLM-L6-v2"):        self.embedder = SentenceTransformer(model_name)        self.corpus = []        self.corpus_embeddings = None    def build_index(self, documents: list[str]):        """Mengonversi dokumen teks menjadi matriks embedding."""        self.corpus = documents        self.corpus_embeddings = self.embedder.encode(documents, convert_to_tensor=True)    def retrieve_context(self, query: str, top_k: int = 2) -> list[str]:        """Pencarian dokumen paling relevan berdasarkan skor kosinus similaritas."""        query_embedding = self.embedder.encode(query, convert_to_tensor=True)        scores = util.cos_sim(query_embedding, self.corpus_embeddings)[0]        top_indices = torch.topk(scores, k=top_k).indices        return [self.corpus[idx] for idx in top_indices]    def generate_prompt(self, query: str, retrieved_docs: list[str]) -> str:        """Penyusunan prompt teraugmentasi dengan konteks referensi."""        context_str = "
---
".join(retrieved_docs)        return (            f"Konteks Referensi:
{context_str}

